data.query:
query WorkOrderProcessDistributionGroup($whereDG: WorkOrderProcessDistributionGroupWhereInput, $wherePS: ProductionSetupWhereInput) {
  workOrderProcessDistributionGroup(where: $whereDG) {
    edges {
      node {
        id
        sequential
        requireParallelOutput
        parallelPositions
        workcenter {
          id
          code
          concurrency
          shiftGroupId
          productionSetup {
            id
            workcenterId
            mode {
              id
              name
            }
            eventId
            operators {
              edges {
                node {
                  id
                  employeeId
                }
              }
            }
            outputs {
              edges {
                node {
                  id
                }
              }
            }
          }
          modeGroup {
            modeList(where: {defaultNewSetup: {_eq: true}}) {
              edges {
                node {
                  defaultEventId
                  mode {
                    id
                  }
                }
              }
            }
          }
        }
        workOrderProcessDistributionStatusId
        distributions(where: {virtual: {_eq: false}}) {
          total
          edges {
            node {
              id
              balanceQuantity
              requiredQuantity
              idealRate
              standardRate
              setupRate
              cycleTime
              setupRate
              setupOperators
              workOrderProcessDistributionStatusId
              materialUsage
              workOrder {
                id
                productId
                actualStartAt
                workOrderStatusId
                workOrderProcesses {
                  edges {
                    node {
                      id
                      order
                      productStrategyProcessId
                      productStrategy {
                        id
                        productId
                      }
                    }
                  }
                }
              }
              workOrderProcess {
                id
                order
                code
                idealRate
                transferSerial
                productionTypeId
                workOrderProcessStatusId
                unitPerCycle
                workOrderProcessBoms {
                  edges {
                    node {
                      bomTypeId
                      id
                      componentProductId
                      componentProductStrategyId
                      componentProductStrategyProcessId
                      assemblyProductStrategyProcessId
                      standardUsage
                      unitPerCycle
                      minimumUsage
                      maximumUsage
                      productStrategyProcessBomId
                      order
                      workOrderProcessId
                      consumptionModeId
                      reference
                      standardPackQuantity
                      defaultPackaging
                    }
                  }
                }
                productStrategyProcessId
                processId
                productStrategy {
                  productId
                }
              }
            }
          }
        }
        virtual: distributions(where: {virtual: {_eq: true}}) {
          edges {
            node {
              id
              balanceQuantity
              requiredQuantity
              idealRate
              standardRate
              setupRate
              cycleTime
              setupRate
              setupOperators
              workOrderProcessDistributionStatusId
              parentProcess {
                id
                bom: assemblyBoms(where: {bomTypeId: {_in: ["Product", "Charge", "Packaging", "Tooling"]}}) {
                  edges {
                    node {
                      bomTypeId
                      id
                      componentProductId
                      componentProductStrategyId
                      componentProductStrategyProcessId
                      assemblyProductStrategyProcessId
                      standardUsage
                      unitPerCycle
                      minimumUsage
                      maximumUsage
                      order
                      consumptionModeId
                      reference
                      standardPackQuantity
                      defaultPackaging
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  productionSetup(where: $wherePS) {
    edges {
      node {
        id
        workcenter {
          shiftGroupId
        }
        modeId
        eventId
      }
    }
  }
}

