(
  $L := $state.context.LOCAL;
  $g := $L.group;
  $distribution := $g.distributions.edges.node;
  $virtual := $g.virtual.edges.node;



    $payloads:= [$distribution.(
      $id := $cuid();
      $dist := $;
      $cmpbom := [workOrderProcess.workOrderProcessBoms.edges.node[bomTypeId="Product" and $not(componentProductStrategyProcessId in [$g.virtual.edges.node.parentProcess.bom.edges.node.componentProductStrategyProcessId])].(
        $d := %.%.%.%;
        {     
          "create": {
            "id":$d.workOrderProcess.id & "-" & componentProductId,
            "order": order,
            "productionSetupOutputId": $id,
            "componentProductId": componentProductId,
            "componentProductStrategyId":componentProductStrategyId,
            "componentProductStrategyProcessId":componentProductStrategyProcessId,
            "assemblyProductStrategyProcessId": assemblyProductStrategyProcessId,
            "workOrderProcessId": $d.workOrderProcess.id,
            "productStrategyProcessBomId": productStrategyProcessBomId,
            "workOrderProcessBomId": id,
            "standardUsage": standardUsage,
            "bomTypeId": "Product",
            "minimumUsage": minimumUsage,
            "maximumUsage":maximumUsage,
            "reference": reference,
            "consumptionModeId": consumptionModeId
          }
      })];

        /* "id":$dist.id & "-" & componentProductId, */
             /* "workOrderProcessBomId": id, */
      $shdbom := [$virtual.parentProcess.bom.edges.node.(
        {     
          "create": {

            "order": order,
            "productionSetupOutputId": $id,
            "componentProductId": componentProductId,
            "componentProductStrategyId":componentProductStrategyId,
            "componentProductStrategyProcessId":componentProductStrategyProcessId,
            "assemblyProductStrategyProcessId": assemblyProductStrategyProcessId,
            "workOrderProcessId": $dist.workOrderProcess.id,
            "productStrategyProcessBomId": id,

            "standardUsage": standardUsage*$dist.materialUsage,
            "bomTypeId": "Product",
            "minimumUsage": $coalesce([minimumUsage,0]) * $dist.materialUsage,
            "maximumUsage":$coalesce([maximumUsage,0]) * $dist.materialUsage,
            "reference": reference,
            "consumptionModeId": consumptionModeId
          }
        }
      )];
      $wipbom := [(
        $d := id;
        $wip := $state.context.LOCAL.distributionWip[dist=$d];
        $isNilOrEmpty($wip) ? {} :
          {     
            "create": {

              "order": '0',
              "productionSetupOutputId": $id,
              "componentProductId": $wip.workOrder.productId,
              "componentProductStrategyId":$wip.productStrategy.id,
              "componentProductStrategyProcessId":$wip.productStrategyProcessId,
              "assemblyProductStrategyProcessId": workOrderProcess.productStrategyProcessId,
              "workOrderProcessId": workOrderProcess.id,

              "standardUsage": 1,
              "bomTypeId": "Product",
              "minimumUsage": 1,
              "maximumUsage":1,
              "reference": "Predecessor - WIP",
              "consumptionModeId": workOrderProcess.transferSerial
                ? "Transfer Serial" 
                : "Standard"
            } 
          }
      )];
    {     
      "PSO": [{
        "create": {
          "id": $id,
          "workcenterId": $g.workcenter.id,
          "workOrderDistributionId":$.id, 
          "workOrderDistributionGroupId": $g.id,
          "productStrategyProcessId": $.workOrderProcess.productStrategyProcessId,
          "productId": $.workOrder.productId,
          "workOrderProcessId": $.workOrderProcess.id,
          "workOrderId": $.workOrder.id,
          "productionSetupId": $g.workcenter.productionSetup.id,
          "remainingBalance":$.balanceQuantity,
          "distributionQuantity": $.requiredQuantity,
          "idealRate":$.idealRate,
          "standardRate":$.standardRate,
          "setupRate":$.setupRate,
          "cycleTime":$.cycleTime,
          "unitPerCycle": workOrderProcess.unitPerCycle,
          "virtual":virtual,
          "startAt": $L.time,
          "standardPackQuantity":workOrderProcess.workOrderProcessBoms.edges.node[bomTypeId="Packaging" and defaultPackaging][0].standardPackQuantity
        }
      }],
      "BOM":$append($append($cmpbom, $wipbom[$not($isNilOrEmpty($))]),$shdbom)
    }
    )];
   {
    "payloadPSO": $isNilOrEmpty($virtual) ? [$payloads.PSO] : $append($payloads.PSO,[]), /* Add virtual as output???? */
    "payloadB": [$payloads.BOM]
  } 


)

