data.query:
query Query($where: KanbanRackWhereInput, $orderBy: [KanbanRackOrderByInput!], $first: Int, $after: String) {
  rack:kanbanRack(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
       number
        active
        productId
        productStrategyId
        workcenter {
          id facilityId
        }
        productStrategyProcess{
          order
          id
          standardPositions
          cycleTime
          idealRate
          setupRate
          standardRate
          unitPerCycle
          processId
          productionTypeId
          productStrategy {
            id productId
            strategyProcesses {
              edges {node {
                id order productStrategy {id productId}
              }}
              }
          }
          workcenter {
            id
            code
            concurrency
            shiftGroupId
            productionSetup{
              id
              workcenterId
              mode {
               id name
              }
              eventId
              operators {
                edges {
                  node {
                    id
                    employeeId
                  }
                }
              }
              outputs {
                edges {
                  node {
                    id
                  }
                }
              }
            }
            modeGroup {
              modeList(where: {defaultNewSetup: {_eq: true}}) {
                edges {
                  node {
                    defaultEventId
                    mode {
                      id
                    }
                  }
                }
              }
            }
          }
          boms:assemblyBoms {
            edges {
              node {
                bomTypeId
                id
                componentProductId
                componentProductStrategyId
                componentProductStrategyProcessId
                assemblyProductStrategyProcessId
                standardUsage
                unitPerCycle
                minimumUsage
                maximumUsage

                order

                consumptionModeId
                reference

                defaultPackaging
                standardPackQuantity
              }
            }
          }
        }
        card:kanbanCards(where:{
           active:{
            _eq:true
          },
          available: {
            _eq: true
          }

        }, first:1) {
          edges {
            node {
              id
              number
              cardQuantity
              available

            }
          }
        }
      }
    }
  }
}

